import { refresh } from 'next/cache'
import {
  getCurrentUserId,
  getNotificationPreference,
  setNotificationPreference,
} from '@/lib/preferences'

export async function toggleNotifications(): Promise<void> {
  // Derive identity on the server; never trust a user id from the client.
  const userId = await getCurrentUserId()
  if (!userId) throw new Error('Unauthorized')

  const current = await getNotificationPreference(userId)
  await setNotificationPreference(userId, !current)

  // Re-render the current route and send the fresh RSC payload back in the
  // same response. The user stays on the current page (no redirect).
  refresh()
}
